#Requires -RunAsAdministrator
param([Parameter(Mandatory)][string]$Directory,[Parameter(Mandatory)][int]$OwnerPid,[string]$Action='continue-restored',[Parameter(Mandatory)][string]$CaseId)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
if($Action -notin @('continue-restored','collect-restored') -or $CaseId -notmatch '^[a-f0-9]{32}$'){throw 'An explicit restored case is required'}
Add-Type -Path (Join-Path $PSScriptRoot '../../native/windows/PacketLabGuard.cs')
$guard=[MuPacketLabGuard]::new($OwnerPid,[IO.Path]::GetFullPath($Directory));$report=$guard.Reserve('preview14-'+[guid]::NewGuid().ToString('N')+'.json');$session=$null
function Save($state,$value){[IO.File]::WriteAllText($report,(@{state=$state;time=[DateTime]::UtcNow.ToString('o');result=$value}|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))}
try{
 $machine=[IO.File]::ReadAllText((Join-Path $Directory machine.json))|ConvertFrom-Json;$vm=Get-VM -Id ([guid]$machine.id);$drives=@(Get-VMHardDiskDrive -VM $vm)
 if($vm.State -ne 'Running' -or $vm.Name -ne $machine.name -or $vm.Name -notmatch '^mu-win-clean-[a-f0-9]{32}$' -or $vm.Notes -ne ('MuCodeSandbox clean Windows diagnostic '+$vm.Name) -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -cne [IO.Path]::GetFullPath((Join-Path $Directory trace-artifacts/windows.vhdx)) -or @(Get-VMNetworkAdapter -VM $vm|Where-Object SwitchName).Count){throw 'Disconnected evaluation identity changed'}
 $c=[IO.File]::ReadAllText((Join-Path $Directory guest-seed/private/credentials.json))|ConvertFrom-Json;$session=New-PSSession -VMId $vm.Id -Credential ([pscredential]::new($c.adminUser,(ConvertTo-SecureString $c.adminPassword -AsPlainText -Force)))
 if($Action -eq 'collect-restored'){
  $result=Invoke-Command -Session $session -ArgumentList $CaseId -ScriptBlock {
   param($id)
   $ErrorActionPreference='Stop';$case='C:\MuLab\public\backup-preview14-'+$id;$meta=[IO.File]::ReadAllText((Join-Path $case case.json))|ConvertFrom-Json;$owner=[IO.File]::ReadAllText((Join-Path $case restored-owner.json))|ConvertFrom-Json;$continued=[IO.File]::ReadAllText((Join-Path $case restored-result.json))|ConvertFrom-Json;$station=[IO.File]::ReadAllText((Join-Path $case restored-station-out.log))|ConvertFrom-Json;$audit=[IO.File]::ReadAllText((Join-Path $case restored-audit.json))|ConvertFrom-Json
   if($env:COMPUTERNAME -ne 'MU-CLEAN-LAB' -or $meta.caseId -cne $id -or $meta.version -ne '0.4.66-preview.16' -or -not $continued.complete -or $continued.checks.Count -ne 3 -or @($continued.checks|Where-Object{-not $_.passed}).Count -or $continued.nonce -cne $owner.nonce -or $continued.pid -ne $owner.pid -or -not $station.complete -or $station.exitCode -ne 0 -or $station.pid -ne $owner.pid -or $audit.nonce -cne $owner.nonce -or -not $audit.confirmed -or $continued.nested.restoredPlatformId -ne $audit.platformId -or $continued.nested.creationAttempts -ne 0){throw 'Completed restored identity and independent process exit receipts required'}
   if(@(Get-VM).Count -or @(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -like '*MuCodeSandbox*' -or $_.ExecutablePath -like 'C:\MuLab\product\*' -or $_.ExecutablePath -like 'C:\MuLab\private\preview14-restored-*'}).Count){throw 'A diagnostic VM, product process or launcher remains'}
   $sid=(Get-LocalUser MuLabUser).SID.Value;$ledgerRoot=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sid);$ledger=[IO.File]::ReadAllText((Join-Path $ledgerRoot vms.json));if($ledger -cne [IO.File]::ReadAllText((Join-Path $ledgerRoot vms.backup.json)) -or @((ConvertFrom-Json $ledger).records.PSObject.Properties).Count){throw 'Protected allocations remain'}
   $preserved=[IO.File]::ReadAllText((Join-Path $case resume-preserved.json))|ConvertFrom-Json;if((Get-FileHash -LiteralPath $preserved.copy).Hash.ToLowerInvariant() -ne $preserved.sha256 -or (Test-Path -LiteralPath (Join-Path $case resume-archive.mucwin)) -or @(Get-ChildItem -LiteralPath (Join-Path $case resume-target-runtime) -Directory -Filter 'backup-work-*').Count){throw 'Original copy or staging cleanup changed'}
   $registrationPath='Registry::HKEY_USERS\'+$sid+'\Software\Microsoft\Windows\CurrentVersion\Uninstall\e88eb670-5944-5236-81aa-7c1d3da3d6df'
   if(Test-Path -LiteralPath $registrationPath){$registration=Get-ItemProperty -LiteralPath $registrationPath}else{
    # The private standard-user station has exited and Windows unloaded its hive.
    # Inspect an administrator-private COPY; never mount or write the original.
    $profile=(Get-ItemProperty -LiteralPath ('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\'+$sid)).ProfileImagePath;$source=Join-Path $profile NTUSER.DAT
    if([IO.Path]::GetFullPath($source) -cne 'C:\Users\MuLabUser\NTUSER.DAT' -or ([IO.File]::GetAttributes($source) -band [IO.FileAttributes]::ReparsePoint) -or (Get-Item -LiteralPath $source -Force).Length -gt 128MB){throw 'Only the known synthetic user hive can be audited'}
    $sourceHash=(Get-FileHash -LiteralPath $source).Hash;$copy='C:\MuLab\private\preview16-registry-'+[guid]::NewGuid().ToString('N')+'.hive';$key='MuPreview16Audit-'+[guid]::NewGuid().ToString('N')
    $input=[IO.File]::Open($source,'Open','Read','Read');try{$output=[IO.File]::Open($copy,'CreateNew','Write','None');try{$input.CopyTo($output)}finally{$output.Dispose()}}finally{$input.Dispose()}
    & reg.exe load ('HKU\'+$key) $copy|Out-Null;if($LASTEXITCODE -ne 0){throw 'Private hive copy could not be loaded; preserved'}
    try{$registration=Get-ItemProperty -LiteralPath ('Registry::HKEY_USERS\'+$key+'\Software\Microsoft\Windows\CurrentVersion\Uninstall\e88eb670-5944-5236-81aa-7c1d3da3d6df')}finally{[GC]::Collect();[GC]::WaitForPendingFinalizers();& reg.exe unload ('HKU\'+$key)|Out-Null;if($LASTEXITCODE -ne 0){throw 'Private audit hive remains mounted; inspect it'}}
    if((Get-FileHash -LiteralPath $source).Hash -ne $sourceHash){throw 'Original synthetic profile changed during audit'}
    foreach($file in @($copy,($copy+'.LOG1'),($copy+'.LOG2'))){if([IO.File]::Exists($file)){[IO.File]::Delete($file)}}
   }
   if($registration.DisplayVersion -ne $meta.version -or (Test-Path -LiteralPath ($meta.installed+'.mu-install.json'))){throw 'Installation is not complete'}
   $config=[IO.File]::ReadAllText(('C:\MuLab\approved\preview14-restored-launch-'+$id+'.json'))|ConvertFrom-Json;$priorLaunch=[IO.File]::ReadAllText(('C:\MuLab\approved\preview14-resume-launch-'+$id+'.json'))|ConvertFrom-Json
   if((Get-FileHash C:\MuLab\backup-restored-continue.mjs).Hash.ToLowerInvariant() -ne $config.clientSha256 -or (Get-FileHash C:\MuLab\backup-installed-resume.mjs).Hash.ToLowerInvariant() -ne $priorLaunch.clientSha256){throw 'Executed acceptance inputs changed'}
   $hashes=@{};function HashTree($dir,$prefix){foreach($e in Get-ChildItem -LiteralPath $dir){if($e.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Installed reparse entry'};$name=$prefix+'/'+$e.Name;if($e.PSIsContainer){HashTree $e.FullName $name}else{$hashes[$name]=(Get-FileHash -LiteralPath $e.FullName).Hash.ToLowerInvariant()}}};foreach($name in @('dist','dist-server','desktop')){HashTree (Join-Path $meta.installed ('resources/app/'+$name)) $name}
   $pointer=[IO.File]::ReadAllText((Join-Path $env:ProgramData MuCodeSandbox-HyperVBroker-v1/bin/current.json))|ConvertFrom-Json
   @{caseId=$id;originalInstallation=([IO.File]::ReadAllText((Join-Path $case upgrade-result.json))|ConvertFrom-Json);preboot=([IO.File]::ReadAllText((Join-Path $case resume-result.json))|ConvertFrom-Json);continued=$continued;diagnostic=([IO.File]::ReadAllText((Join-Path $case diagnostic-result.json))|ConvertFrom-Json);auditedRestoredPlatformId=$audit.platformId;installedCodeHashes=$hashes;installedExecutableSha256=(Get-FileHash -LiteralPath (Join-Path $meta.installed 'MuCodeSandbox Windows Preview.exe')).Hash.ToLowerInvariant();installedNodeSha256=(Get-FileHash -LiteralPath (Join-Path $meta.installed resources/node/node.exe)).Hash.ToLowerInvariant();installerSha256=(Get-FileHash -LiteralPath (Join-Path $case setup.exe)).Hash.ToLowerInvariant();fixtureSha256=$config.clientSha256;prebootFixtureSha256=$priorLaunch.clientSha256;brokerSourceDigest=$pointer.sourceDigest;registrationVerified=$true;originalCopyUnchanged=$true;nestedGuestsRemaining=0;installedControllerExited=$true;collectorRetriedWithoutRerunningVm=$true;controllerExitVerifiedByStationReceipt=$true;syntheticAutologonDisabled=((Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon').AutoAdminLogon -eq '0')}
  }
  Stop-VM -VM $vm -Confirm:$false;while((Get-VM -Id $vm.Id).State -ne 'Off'){Start-Sleep -Milliseconds 250};Save 'installed-restored-continuation-complete-evaluation-vm-off' $result;exit 0
 }
 $validation=Invoke-Command -Session $session -ArgumentList $CaseId -ScriptBlock {
  param($id)
  $case='C:\MuLab\public\backup-preview14-'+$id;$prior=[IO.File]::ReadAllText((Join-Path $case resume-result.json))|ConvertFrom-Json;$original=[IO.File]::ReadAllText((Join-Path $case resume-preserve-request.json))|ConvertFrom-Json;$meta=[IO.File]::ReadAllText((Join-Path $case case.json))|ConvertFrom-Json
  if($env:COMPUTERNAME -ne 'MU-CLEAN-LAB' -or $meta.caseId -cne $id -or $meta.version -ne '0.4.66-preview.16' -or $prior.complete -ne $false -or $prior.checks.Count -ne 5 -or $prior.error.code -ne 'ERR_ASSERTION' -or @(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -like '*MuCodeSandbox*' -or $_.ExecutablePath -like 'C:\MuLab\product\*'}).Count){throw 'The exact restored phase must be terminal'}
  $guests=@(Get-VM);$manifest=[IO.File]::ReadAllText((Join-Path $case ('resume-target-runtime/mu-win-'+$original.id.Replace('-','')+'/manifest.json')))|ConvertFrom-Json
  if($guests.Count -ne 1 -or $guests[0].State -ne 'Off' -or [string]$guests[0].Id -ne $manifest.platformId -or $manifest.id -ne $original.id -or $manifest.platformId -eq $original.platformId){throw 'Only the same restored Off VM can continue'}
  if((Test-Path -LiteralPath (Join-Path $case restored-owner.json)) -or (Test-Path -LiteralPath (Join-Path $case restored-result.json))){throw 'An existing restored continuation must be inspected'}
  @{platformId=$manifest.platformId;id=$original.id}
 }
 Copy-Item -LiteralPath (Join-Path $PSScriptRoot clean-host-backup-restored-continue.mjs) -Destination C:\MuLab\backup-restored-continue.mjs -ToSession $session
 Copy-Item -LiteralPath (Join-Path $PSScriptRoot Preview14Station.cs) -Destination C:\MuLab\private\Preview14RestoredStation.cs -ToSession $session
 Save 'continuing-restored-vm' @{caseId=$CaseId;platformId=$validation.platformId}
 $result=Invoke-Command -Session $session -ArgumentList $CaseId,$validation -ScriptBlock {
  param($id,$validation)
  $ErrorActionPreference='Stop';$case='C:\MuLab\public\backup-preview14-'+$id;$meta=[IO.File]::ReadAllText((Join-Path $case case.json))|ConvertFrom-Json;$sid=(Get-LocalUser MuLabUser).SID.Value;$node=Join-Path $meta.installed resources/node/node.exe
  $config=@{caseId=$id;sid=$sid;node=$node;clientSha256=(Get-FileHash C:\MuLab\backup-restored-continue.mjs).Hash.ToLowerInvariant();nodeSha256=(Get-FileHash -LiteralPath $node).Hash.ToLowerInvariant()}
  [IO.File]::WriteAllText(('C:\MuLab\approved\preview14-restored-launch-'+$id+'.json'),($config|ConvertTo-Json -Compress));$launcher='C:\MuLab\private\preview14-restored-'+$id+'.exe'
  Add-Type -TypeDefinition ([IO.File]::ReadAllText('C:\MuLab\private\Preview14RestoredStation.cs')) -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll') -OutputAssembly $launcher -OutputType ConsoleApplication
  $station=Start-Process -FilePath $launcher -ArgumentList @($id,'continue-restored') -WindowStyle Hidden -RedirectStandardOutput (Join-Path $case restored-station-out.log) -RedirectStandardError (Join-Path $case restored-station-error.log) -PassThru
  $null=$station.Handle
  $until=[DateTime]::UtcNow.AddMinutes(2);do{if(Test-Path -LiteralPath (Join-Path $case restored-owner.json)){break};if($station.HasExited -or [DateTime]::UtcNow -gt $until){throw 'Restored continuation not confirmed'};Start-Sleep -Milliseconds 250}while($true)
  $owner=[IO.File]::ReadAllText((Join-Path $case restored-owner.json))|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
  if($owner.caseId -cne $id -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -cne $node -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $sid){throw 'Installed restored process binding changed'}
  $controller=Get-Process -Id $owner.pid;$null=$controller.Handle;$bin=Join-Path $env:ProgramData MuCodeSandbox-HyperVBroker-v1/bin;$pointer=[IO.File]::ReadAllText((Join-Path $bin current.json))|ConvertFrom-Json;$broker=Join-Path $bin $pointer.brokerFile
  if((Get-FileHash -LiteralPath $broker).Hash.ToLowerInvariant() -ne $pointer.brokerSha256){throw 'Protected broker changed'}
  $agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput (Join-Path $case restored-broker-out.log) -RedirectStandardError (Join-Path $case restored-broker-error.log) -PassThru
  $null=$agent.Handle
  $preserved=[IO.File]::ReadAllText((Join-Path $case resume-preserved.json))|ConvertFrom-Json;$until=[DateTime]::UtcNow.AddMinutes(20);$audited=$false
  do{
   if(-not $audited -and (Test-Path -LiteralPath (Join-Path $case restored-audit-request.json))){
    $request=[IO.File]::ReadAllText((Join-Path $case restored-audit-request.json))|ConvertFrom-Json;$current=Get-VM -Id ([guid]$validation.platformId);$disk=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sid+'/vms/'+$validation.id+'/disk.vhdx');$d=@(Get-VMHardDiskDrive -VM $current)
    if($request.nonce -cne $owner.nonce -or $request.platformId -ne $validation.platformId -or $request.id -ne $validation.id -or $current.State -ne 'Off' -or $d.Count -ne 1 -or [IO.Path]::GetFullPath($d[0].Path) -cne $disk -or (Get-FileHash -LiteralPath $disk).Hash.ToLowerInvariant() -ne $request.currentDisk.sha256 -or (Get-FileHash -LiteralPath $preserved.copy).Hash.ToLowerInvariant() -ne $preserved.sha256){throw 'Current restored disk or independent original changed'}
    [IO.File]::WriteAllText((Join-Path $case restored-audit.json),(@{nonce=$owner.nonce;confirmed=$true;platformId=$validation.platformId;currentDiskSha256=$request.currentDisk.sha256}|ConvertTo-Json -Compress));$audited=$true
   }
   if(Test-Path -LiteralPath (Join-Path $case restored-result.json)){break};if([DateTime]::UtcNow -gt $until){throw 'The exact restored continuation remains pending; no restart'};Start-Sleep -Milliseconds 500
  }while($true)
  $continued=[IO.File]::ReadAllText((Join-Path $case restored-result.json))|ConvertFrom-Json
  if(-not $continued.complete -or $continued.nonce -cne $owner.nonce -or $continued.checks.Count -ne 3 -or -not $audited -or -not $controller.WaitForExit(15000) -or -not $agent.WaitForExit(45000) -or -not $station.WaitForExit(15000) -or $station.ExitCode -ne 0 -or @(Get-VM).Count -or (Get-FileHash -LiteralPath $preserved.copy).Hash.ToLowerInvariant() -ne $preserved.sha256){throw 'Restored continuation or independent cleanup did not pass'}
  $ledgerRoot=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sid);$ledger=[IO.File]::ReadAllText((Join-Path $ledgerRoot vms.json));if($ledger -cne [IO.File]::ReadAllText((Join-Path $ledgerRoot vms.backup.json)) -or @((ConvertFrom-Json $ledger).records.PSObject.Properties).Count){throw 'Protected allocations remain'}
  $registration=Get-ItemProperty -LiteralPath ('Registry::HKEY_USERS\'+$sid+'\Software\Microsoft\Windows\CurrentVersion\Uninstall\e88eb670-5944-5236-81aa-7c1d3da3d6df');if($registration.DisplayVersion -ne $meta.version -or (Test-Path -LiteralPath ($meta.installed+'.mu-install.json'))){throw 'Installation is not complete'}
  $hashes=@{};function HashTree($dir,$prefix){foreach($e in Get-ChildItem -LiteralPath $dir){if($e.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Installed reparse entry'};$name=$prefix+'/'+$e.Name;if($e.PSIsContainer){HashTree $e.FullName $name}else{$hashes[$name]=(Get-FileHash -LiteralPath $e.FullName).Hash.ToLowerInvariant()}}};foreach($name in @('dist','dist-server','desktop')){HashTree (Join-Path $meta.installed ('resources/app/'+$name)) $name}
  $priorLaunch=[IO.File]::ReadAllText(('C:\MuLab\approved\preview14-resume-launch-'+$id+'.json'))|ConvertFrom-Json;if((Get-FileHash C:\MuLab\backup-installed-resume.mjs).Hash.ToLowerInvariant() -ne $priorLaunch.clientSha256){throw 'Prior preboot validation input changed'}
  @{caseId=$id;originalInstallation=([IO.File]::ReadAllText((Join-Path $case upgrade-result.json))|ConvertFrom-Json);preboot=([IO.File]::ReadAllText((Join-Path $case resume-result.json))|ConvertFrom-Json);continued=$continued;diagnostic=([IO.File]::ReadAllText((Join-Path $case diagnostic-result.json))|ConvertFrom-Json);auditedRestoredPlatformId=$validation.platformId;installedCodeHashes=$hashes;installedExecutableSha256=(Get-FileHash -LiteralPath (Join-Path $meta.installed 'MuCodeSandbox Windows Preview.exe')).Hash.ToLowerInvariant();installedNodeSha256=$config.nodeSha256;installerSha256=(Get-FileHash -LiteralPath (Join-Path $case setup.exe)).Hash.ToLowerInvariant();fixtureSha256=$config.clientSha256;prebootFixtureSha256=$priorLaunch.clientSha256;brokerSourceDigest=$pointer.sourceDigest;registrationVerified=$true;originalCopyUnchanged=$true;nestedGuestsRemaining=0;installedControllerExited=$true;syntheticAutologonDisabled=((Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon').AutoAdminLogon -eq '0')}
 }
 Stop-VM -VM $vm -Confirm:$false;while((Get-VM -Id $vm.Id).State -ne 'Off'){Start-Sleep -Milliseconds 250};Save 'installed-restored-continuation-complete-evaluation-vm-off' $result
}catch{Save 'failed' @{message=$_.Exception.Message;stack=$_.ScriptStackTrace};throw}
finally{if($session){Remove-PSSession $session};$guard.Dispose()}
